cd /workspace/testbed && node -e "
const XLSX = require('xlsx');
const wb = XLSX.readFile('data/order_summary.xlsx');
for (const name of wb.SheetNames) {
  console.log('=== Sheet:', name, '===');
  const data = XLSX.utils.sheet_to_json(wb.Sheets[name]);
  console.log(JSON.stringify(data, null, 2));
}
"

const { Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell, WidthType, BorderStyle, AlignmentType, HeadingLevel } = require("docx");
const fs = require("fs");

function cell(text, bold = false) {
  return new TableCell({
    children: [new Paragraph({ children: [new TextRun({ text, bold, size: 22 })] })],
    width: { size: 50, type: WidthType.PERCENTAGE },
  });
}

function tableRow(col1, col2, headerRow = false) {
  return new TableRow({ children: [cell(col1, headerRow), cell(col2, headerRow)] });
}

const doc = new Document({
  sections: [{
    children: [
      // Title
      new Paragraph({ heading: HeadingLevel.TITLE, children: [new TextRun({ text: "Order Summary Analysis", bold: true })] }),
      new Paragraph({ children: [new TextRun({ text: "Source: data/order_summary.xlsx", italics: true, color: "666666", size: 22 })] }),
      new Paragraph({}),

      // Overview
      new Paragraph({ heading: HeadingLevel.HEADING_1, children: [new TextRun("Overview")] }),
      new Paragraph({ bullet: { level: 0 }, children: [new TextRun({ text: "27 total orders", bold: true }), new TextRun(" across a single sheet ("Orders"), all placed on 2026-09-02 (25 orders) and 2026-09-04 (2 orders).")] }),
      new Paragraph({ bullet: { level: 0 }, children: [new TextRun({ text: "24 confirmed / 3 cancelled", bold: true }), new TextRun(" — an 89% confirmation rate.")] }),
      new Paragraph({}),

      // Revenue
      new Paragraph({ heading: HeadingLevel.HEADING_1, children: [new TextRun("Revenue")] }),
      new Table({
        rows: [
          tableRow("Metric", "Value", true),
          tableRow("Gross total (all orders)", "$2,078"),
          tableRow("Cancelled order value", "$186 (ORD-6C71B1: $79, ORD-12AAA3: $39, ORD-4A5831: $68)"),
          tableRow("Net confirmed revenue", "$1,892"),
          tableRow("Average confirmed order value", "~$78.83"),
          tableRow("Smallest order", "$14 (AeroLoop Silicone Cable Organizer)"),
          tableRow("Largest order", "$201 (ORD-CCC96C — 3 items)"),
        ],
        width: { size: 100, type: WidthType.PERCENTAGE },
      }),
      new Paragraph({}),

      // Customer Breakdown
      new Paragraph({ heading: HeadingLevel.HEADING_1, children: [new TextRun("Customer Breakdown")] }),
      new Paragraph({ bullet: { level: 0 }, children: [new TextRun({ text: "Maya Chen", bold: true }), new TextRun(" is the most active customer with 7 orders (2 cancelled, 5 confirmed) totaling $477 confirmed.")] }),
      new Paragraph({ bullet: { level: 0 }, children: [new TextRun({ text: "Evan Parker", bold: true }), new TextRun(" placed 4 orders, all confirmed, totaling $276.")] }),
      new Paragraph({ bullet: { level: 0 }, children: [new TextRun({ text: "Alicia Morgan", bold: true }), new TextRun(" has 2 confirmed orders ($137).")] }),
      new Paragraph({ bullet: { level: 0 }, children: [new TextRun("The remaining orders are spread across Nina Patel, Jordan Alvarez, Sofia Ramirez, and 8 anonymous/user-ID customers (1 order each).")] }),
      new Paragraph({}),

      // Top Products
      new Paragraph({ heading: HeadingLevel.HEADING_1, children: [new TextRun("Top Products (by Frequency of Appearance)")] }),
      new Table({
        rows: [
          new TableRow({ children: [cell("#", true), cell("Product", true), cell("Orders", true)] }),
          new TableRow({ children: [cell("1"), cell("LogiTech Wireless Mouse M310"), cell("13 orders")] }),
          new TableRow({ children: [cell("2"), cell("OXO SoftWorks 3-Piece Mixing Bowl Set"), cell("7 orders")] }),
          new TableRow({ children: [cell("3"), cell("Everyday Canvas Tote Bag"), cell("5 orders")] }),
          new TableRow({ children: [cell("4"), cell("Bamboo Desk Organizer Set"), cell("4 orders")] }),
          new TableRow({ children: [cell("5"), cell("Levi's Classic Cotton T-Shirt"), cell("4 orders")] }),
          new TableRow({ children: [cell("6"), cell("Northline Wool Blend Throw Blanket"), cell("3 orders")] }),
        ],
        width: { size: 100, type: WidthType.PERCENTAGE },
      }),
      new Paragraph({}),

      // Key Takeaways
      new Paragraph({ heading: HeadingLevel.HEADING_1, children: [new TextRun("Key Takeaways")] }),
      new Paragraph({ bullet: { level: 0 }, children: [new TextRun({ text: "Tech accessories dominate: ", bold: true }), new TextRun("The LogiTech mouse appears in nearly half of all orders, often bundled with other items.")] }),
      new Paragraph({ bullet: { level: 0 }, children: [new TextRun({ text: "Cancellation risk is low ", bold: true }), new TextRun("(11%), but notably Maya Chen accounts for 2 of the 3 cancellations — worth investigating.")] }),
      new Paragraph({ bullet: { level: 0 }, children: [new TextRun({ text: "Multi-item orders are common: ", bold: true }), new TextRun("19 of 27 orders contain 2+ items, suggesting effective cross-selling.")] }),
      new Paragraph({ bullet: { level: 0 }, children: [new TextRun("All activity is concentrated on just two days, so this appears to be a snapshot rather than a long-term dataset.")] }),
    ],
  }],
});

Packer.toBuffer(doc).then(buf => {
  fs.writeFileSync("data/order_summary_analysis.docx", buf);
  console.log("Saved: data/order_summary_analysis.docx (" + buf.length + " bytes)");
});
